package com.aoo.bcg.wordcard;import com.aoo.bcg.gamespi.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class YchpNineStageAcceptanceTest{@Test void nineStagesAndFlowers(){YchpGameProvider p=new YchpGameProvider();YchpSession s=(YchpSession)p.roomFactory().create(new RoomCreationContext(40701,10,Map.of("playerCount",2))).requireAuthoritativeSession();StatePayload base=StatePayload.copyOf(s.authoritativeState());s.execute(c(1,1,20,"join",Map.of()));s.execute(c(2,1,20,"ready",Map.of()));Map<String,Object>v=s.execute(c(3,0,10,"start",Map.of())).body().asMap();Map<?,?>seats=(Map<?,?>)v.get("seats");assertEquals(14,((Map<?,?>)seats.get(0)).get("cardCount"));assertEquals(13,((Map<?,?>)seats.get(1)).get("cardCount"));int card=(Integer)((List<?>)((Map<?,?>)seats.get(0)).get("cards")).getFirst();s.execute(c(4,0,10,"operation",Map.of("operation","DISCARD","cards",List.of(card))));s.execute(c(5,1,20,"operation",Map.of("operation","PASS")));StatePayload replay=p.eventReplayProvider().orElseThrow().replay(base,s.events());assertEquals(s.authoritativeState(),replay.asMap());assertEquals(s.viewFor(20),p.restoreAuthoritativeSession(replay).orElseThrow().viewFor(20));assertEquals(144,YchpRules.deck().size());}@Test void atomicProvider(){assertEquals(0,ServiceLoader.load(GameProvider.class).stream().filter(x->x.type()==YchpGameProvider.class).count());}private static GameCommandRequest c(long n,int seat,long p,String a,Map<String,Object>payload){return new GameCommandRequest("wordcard.ychp.dispatch","y"+n,n,40701,0,"1.0.0",String.valueOf(p),seat,Map.of("action",a,"payload",payload));}}
